=== DIFF: lib/closet/__tests__/update-schema.test.ts ===
@@ -0,0 +1,40 @@
+import { UpdateSchema } from "../update-schema";
+
+const valid = {
+  name: "Ribbed crewneck",
+  brand: "Uniqlo",
+  category: "Tops",
+  subcategory: "Ribbed knit",
+  colors: ["navy"],
+  pattern: "solid",
+  material: "Merino wool",
+  texture: "Ribbed",
+  formality: 3,
+  seasons: ["Autumn", "Winter"],
+  price: 79.99,
+};
+
+test("every AI-written field can be updated by the user", () => {
+  const parsed = UpdateSchema.parse(valid);
+  expect(parsed.colors).toEqual(["navy"]);
+  expect(parsed.texture).toBe("Ribbed");
+  expect(parsed.pattern).toBe("solid");
+  expect(parsed.price).toBe(79.99);
+});
+
+test("price is optional and nullable — most items have no recorded price", () => {
+  expect(UpdateSchema.parse({ ...valid, price: null }).price).toBeNull();
+});
+
+test("a negative price is rejected", () => {
+  expect(() => UpdateSchema.parse({ ...valid, price: -5 })).toThrow();
+});
+
+test("an empty season set is rejected rather than silently defaulted", () => {
+  expect(() => UpdateSchema.parse({ ...valid, seasons: [] })).toThrow();
+});
+
+test("material and texture are held to the shared vocabulary here too", () => {
+  expect(() => UpdateSchema.parse({ ...valid, material: "unobtainium" })).toThrow();
+  expect(() => UpdateSchema.parse({ ...valid, texture: "sparkly" })).toThrow();
+});


=== DIFF: lib/closet/update-schema.ts ===
@@ -0,0 +1,29 @@
+import { z } from "zod";
+import { TagSchema } from "@/lib/ai/tagging-schema";
+
+/**
+ * Lives outside the Server Action module so it can be unit-tested: a
+ * "use server" file may only export async functions.
+ *
+ * Every field the tagger writes appears here. CLAUDE.md treats AI tags as a
+ * draft, so a tag the model can set and the user cannot correct is a defect —
+ * `colors` in particular feeds the generator's colour harmony scoring.
+ *
+ * `price` is the exception: the tagger never writes it (a photo cannot tell you
+ * what something cost), so it is user-entered only. Nullable because most items
+ * have no recorded price, and cost-per-wear must divide by nothing rather than
+ * by a fabricated zero.
+ */
+export const UpdateSchema = z.object({
+  name: z.string().nullable(),
+  brand: z.string().nullable(),
+  category: TagSchema.shape.category,
+  subcategory: z.string().nullable(),
+  colors: TagSchema.shape.colors,
+  pattern: TagSchema.shape.pattern,
+  material: TagSchema.shape.material,
+  texture: TagSchema.shape.texture,
+  formality: TagSchema.shape.formality,
+  seasons: TagSchema.shape.seasons,
+  price: z.number().nonnegative().nullable(),
+});


Investigate per the method in your instructions, then return the findings list.

