"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { updateItem, archiveItem } from "@/app/closet/[itemId]/actions";
import { Chip } from "@/components/ui-fitcheck/chip";
import { Kicker } from "@/components/ui-fitcheck/kicker";
import type { Tags } from "@/lib/ai/tagging-schema";

import { ColorPicker } from "./color-picker";
import {
  CATEGORIES,
  SEASONS,
  FORMALITY_LABEL,
  MATERIALS,
  TEXTURES,
  PATTERNS,
} from "@/lib/closet/vocab";

// See the note in confirm-form.tsx — CATEGORIES carries Fragrance because it is
// derived from TagSchema; the picker offers the wearable families.
const PICKABLE = CATEGORIES.filter((c) => c !== "Fragrance");

export type DetailItem = {
  id: string;
  name: string | null;
  brand: string | null;
  category: Tags["category"];
  subcategory: string | null;
  colors: string[];
  material: string | null;
  texture: string | null;
  pattern: string | null;
  price: number | null;
  formality: number | null;
  seasons: string[];
};

export function ItemDetail({
  item,
  imageUrl,
  brandSuggestions,
}: {
  item: DetailItem;
  imageUrl: string;
  brandSuggestions: string[];
}) {
  const router = useRouter();
  const [name, setName] = useState(item.name ?? "");
  const [brand, setBrand] = useState(item.brand ?? "");
  const [material, setMaterial] = useState(item.material ?? "");
  const [category, setCategory] = useState<Tags["category"]>(item.category);
  const [formality, setFormality] = useState(item.formality ?? 3);
  const [seasons, setSeasons] = useState<string[]>(item.seasons);
  const [colors, setColors] = useState<string[]>(item.colors);
  const [texture, setTexture] = useState(item.texture ?? "Flat");
  const [pattern, setPattern] = useState(item.pattern ?? "solid");
  const [subcategory, setSubcategory] = useState(item.subcategory ?? "");
  const [price, setPrice] = useState(item.price?.toString() ?? "");
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);

  function toggleSeason(s: string) {
    setSeasons((cur) => (cur.includes(s) ? cur.filter((x) => x !== s) : [...cur, s]));
  }

  function save() {
    setError(null);
    start(async () => {
      try {
        await updateItem(item.id, {
          name: name || null,
          brand: brand || null,
          category,
          // "Unknown" is not in the vocabulary — it was fabricated here and
          // would now fail validation. "Other" is the real escape hatch.
          material: material || "Other",
          subcategory: subcategory || null,
          colors,
          texture,
          pattern,
          // An empty box means "not recorded", not zero — cost-per-wear must
          // not divide by a price the user never gave.
          price: price.trim() === "" ? null : Number(price),
          formality,
          seasons: seasons.length ? seasons : ["Spring"],
        });
        router.push("/closet");
      } catch (e) {
        setError(e instanceof Error ? e.message : "Save failed");
      }
    });
  }

  function remove() {
    if (!confirm("Remove this piece from your closet?")) return;
    setError(null);
    start(async () => {
      try {
        await archiveItem(item.id);
      } catch (e) {
        setError(e instanceof Error ? e.message : "Failed to remove");
      }
    });
  }

  return (
    <main className="flex flex-1 flex-col gap-5 px-6 pb-7 pt-12">
      <button
        onClick={() => router.back()}
        className="self-start text-2xl leading-none text-muted-foreground"
        aria-label="Back"
      >
        ‹
      </button>

      <div className="grid aspect-[1.3] place-items-center rounded-[18px] bg-surface-1 shadow-[inset_0_0_0_1px_rgba(237,230,216,0.07)]">
        {imageUrl ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={imageUrl} alt={name} className="size-full object-contain p-6" />
        ) : null}
      </div>

      <input
        value={name}
        onChange={(e) => setName(e.target.value)}
        placeholder="Name"
        className="rounded-[12px] border border-[--input] bg-surface-1 px-4 py-3 font-serif text-lg text-foreground outline-none focus:border-brand"
      />

      <input
        list="brand-suggestions"
        value={brand}
        onChange={(e) => setBrand(e.target.value)}
        placeholder="Brand (optional)"
        className="-mt-2 rounded-[12px] border border-[--input] bg-surface-1 px-4 py-3 text-sm text-foreground outline-none focus:border-brand"
      />
      <datalist id="brand-suggestions">
        {brandSuggestions.map((b) => (
          <option key={b} value={b} />
        ))}
      </datalist>

      <div>
        <Kicker className="mb-2 block">Category</Kicker>
        <div className="flex flex-wrap gap-2">
          {PICKABLE.map((c) => (
            <Chip key={c} variant="select" active={category === c} onClick={() => setCategory(c)}>
              {c}
            </Chip>
          ))}
        </div>
      </div>

      <div>
        <Kicker className="mb-2 block">Material</Kicker>
        {/* A chip row, not free text: `material` is a constrained enum now, so
            anything typed outside the vocabulary fails validation on save. */}
        <div className="flex flex-wrap gap-2">
          {MATERIALS.map((m) => (
            <Chip
              key={m}
              variant="select"
              active={material === m}
              onClick={() => setMaterial(m)}
            >
              {m}
            </Chip>
          ))}
        </div>
      </div>

      <div>
        <Kicker className="mb-2 block">Formality · {FORMALITY_LABEL[formality]}</Kicker>
        <div className="flex gap-2">
          {[1, 2, 3, 4, 5].map((n) => (
            <button
              key={n}
              onClick={() => setFormality(n)}
              className={`h-2 flex-1 rounded-full ${n <= formality ? "bg-brand" : "bg-foreground/10"}`}
              aria-label={`Formality ${n}`}
            />
          ))}
        </div>
      </div>

      <div>
        <Kicker className="mb-2 block">Seasons</Kicker>
        <div className="flex flex-wrap gap-2">
          {SEASONS.map((s) => (
            <Chip key={s} variant="select" active={seasons.includes(s)} onClick={() => toggleSeason(s)}>
              {s}
            </Chip>
          ))}
        </div>
      </div>

      <div>
        <Kicker className="mb-2 block">Subcategory</Kicker>
        <input
          aria-label="Subcategory"
          value={subcategory}
          onChange={(e) => setSubcategory(e.target.value)}
          className="w-full rounded-[12px] border border-[--input] bg-surface-1 px-4 py-3 text-sm text-foreground outline-none focus:border-brand"
        />
      </div>

      <div>
        <Kicker className="mb-2 block">Colour</Kicker>
        <ColorPicker value={colors} onChange={setColors} />
      </div>

      <div>
        <Kicker className="mb-2 block">Texture</Kicker>
        <div className="flex flex-wrap gap-2">
          {TEXTURES.map((t) => (
            <Chip key={t} variant="select" active={texture === t} onClick={() => setTexture(t)}>
              {t}
            </Chip>
          ))}
        </div>
      </div>

      <div>
        <Kicker className="mb-2 block">Pattern</Kicker>
        <div className="flex flex-wrap gap-2">
          {PATTERNS.map((p) => (
            <Chip key={p} variant="select" active={pattern === p} onClick={() => setPattern(p)}>
              {p}
            </Chip>
          ))}
        </div>
      </div>

      <div>
        <Kicker className="mb-2 block">Price paid</Kicker>
        <input
          aria-label="Price paid"
          inputMode="decimal"
          value={price}
          onChange={(e) => setPrice(e.target.value)}
          placeholder="Optional — enables cost per wear"
          className="w-full rounded-[12px] border border-[--input] bg-surface-1 px-4 py-3 text-sm text-foreground outline-none focus:border-brand"
        />
      </div>
      {error && <p className="text-sm text-brand">{error}</p>}

      <div className="flex-1" />
      <button
        onClick={save}
        disabled={pending}
        className="rounded-[12px] bg-foreground py-[17px] text-center font-semibold text-canvas disabled:opacity-60"
      >
        {pending ? "Saving…" : "Save"}
      </button>
      <button
        onClick={remove}
        disabled={pending}
        className="text-center text-sm text-brand-deep"
      >
        Remove from closet
      </button>
    </main>
  );
}

import { z } from "zod";

// MATERIALS and TEXTURES are defined HERE rather than imported from
// lib/closet/vocab.ts: vocab derives CATEGORIES/SEASONS from this schema, so
// importing back would be a cycle. `vocab.ts` re-exports these two, and remains
// the module every UI surface reads from.

/**
 * What the garment is made of.
 *
 * `Merino wool` is listed separately from `Wool` on purpose: they behave
 * differently in heat, and one undifferentiated "wool" is exactly the
 * conflation that makes warmth rules wrong. Warmth is decided by fibre AND
 * construction — see TEXTURES.
 */
export const MATERIALS = [
  "Cotton",
  "Wool",
  "Merino wool",
  "Cashmere",
  "Linen",
  "Silk",
  "Denim",
  "Leather",
  "Suede",
  "Faux leather",
  "Canvas",
  "Corduroy",
  "Tweed",
  "Fleece",
  "Shearling",
  "Down",
  "Polyester",
  "Acrylic",
  "Nylon",
  "Viscose",
  "Modal",
  "Lyocell",
  "Stainless steel",
  "Gold",
  "Silver",
  "Rubber",
  "Other",
] as const;

/**
 * How the fabric is built — knit structure and surface finish. A separate
 * dimension from material: a ribbed merino knit and a flat merino shirt share a
 * material and read completely differently, in both warmth and formality.
 *
 * `Other` is the escape hatch, and the one value deliberately shared with
 * MATERIALS. Without it a required `z.enum` forces the model to mislabel rather
 * than admit it cannot tell from a photo.
 */
export const TEXTURES = [
  "Flat",
  "Ribbed",
  "Cable knit",
  "Waffle",
  "Chunky knit",
  "Fine knit",
  "Brushed",
  "Fleece-back",
  "Twill",
  "Herringbone",
  "Quilted",
  "Pile",
  "Open knit",
  "Terry",
  "Seersucker",
  "Other",
] as const;

// Categories + seasons match the prototype (Title case) so tags line up with
// the closet filters and the generator.
export const TagSchema = z.object({
  category: z.enum(["Tops", "Bottoms", "Outerwear", "Shoes", "Accessories", "Fragrance"]),
  subcategory: z.string().min(1),
  colors: z.array(z.string()).min(1).max(3),
  pattern: z.enum(["solid", "striped", "check", "print", "other"]),
  material: z.enum(MATERIALS),
  texture: z.enum(TEXTURES),
  formality: z.number().int().min(1).max(5),
  seasons: z.array(z.enum(["Spring", "Summer", "Autumn", "Winter"])).min(1),
});
export type Tags = z.infer<typeof TagSchema>;

// Anthropic structured outputs (output_config.format) only accept type/enum/shape
// keywords — NOT the numeric (minimum/maximum/multipleOf), string (min/maxLength),
// or array (min/maxItems/uniqueItems) validation keywords that z.toJSONSchema()
// emits from our .min()/.max()/.int() refinements. Sending them 400s. We strip them
// here; the exact bounds are still enforced after the call by TagSchema.parse().
const UNSUPPORTED_JSON_SCHEMA_KEYWORDS = new Set([
  "minimum", "maximum", "exclusiveMinimum", "exclusiveMaximum", "multipleOf",
  "minLength", "maxLength",
  "minItems", "maxItems", "uniqueItems",
]);

export function forStructuredOutput(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(forStructuredOutput);
  if (node && typeof node === "object") {
    const out: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(node)) {
      if (UNSUPPORTED_JSON_SCHEMA_KEYWORDS.has(key)) continue;
      out[key] = forStructuredOutput(value);
    }
    // Structured outputs require every object to forbid extra properties.
    if (out.type === "object" && !("additionalProperties" in out)) {
      out.additionalProperties = false;
    }
    return out;
  }
  return node;
}

// Zod 4 native JSON Schema, sanitised for Anthropic's output_config.format.
export const taggingJsonSchema = forStructuredOutput(
  z.toJSONSchema(TagSchema),
) as Record<string, unknown>;

